//! Embedded per-target link inputs (runtime object, libc/CRT, stubs) keyed by
//! `driver::TARGETS` names. Generated by `tools/gen_assets.sh`.

#[derive(Debug)]
pub struct TargetAssets {
    pub files: &'static [(&'static str, &'static [u8])],
}

macro_rules! define_target {
    ($static_name:ident, $dir:literal, [$($file:literal),* $(,)?]) => {
        pub static $static_name: TargetAssets = TargetAssets {
            files: &[
                $(($file, include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/", $dir, "/", $file)) as &[u8]),)*
            ],
        };
    };
}

define_target!(
    X86_64_LINUX,
    "x86_64-linux",
    [
        "runtime.o",
        "crt1.o",
        "crti.o",
        "crtn.o",
        "libc.a",
        "libzigc.a",
        "libcompiler_rt.a",
    ]
);
define_target!(
    AARCH64_LINUX,
    "aarch64-linux",
    [
        "runtime.o",
        "crt1.o",
        "crti.o",
        "crtn.o",
        "libc.a",
        "libzigc.a",
        "libcompiler_rt.a",
    ]
);
define_target!(
    X86_64_WINDOWS,
    "x86_64-windows",
    [
        "runtime.o",
        "crt2.o",
        "libmingw32.a",
        "libzigc.a",
        "libcompiler_rt.a",
        "advapi32.lib",
        "kernel32.lib",
        "ntdll.lib",
        "shell32.lib",
        "user32.lib",
        "api-ms-win-crt-conio-l1-1-0.lib",
        "api-ms-win-crt-convert-l1-1-0.lib",
        "api-ms-win-crt-environment-l1-1-0.lib",
        "api-ms-win-crt-filesystem-l1-1-0.lib",
        "api-ms-win-crt-heap-l1-1-0.lib",
        "api-ms-win-crt-locale-l1-1-0.lib",
        "api-ms-win-crt-math-l1-1-0.lib",
        "api-ms-win-crt-multibyte-l1-1-0.lib",
        "api-ms-win-crt-private-l1-1-0.lib",
        "api-ms-win-crt-process-l1-1-0.lib",
        "api-ms-win-crt-runtime-l1-1-0.lib",
        "api-ms-win-crt-stdio-l1-1-0.lib",
        "api-ms-win-crt-string-l1-1-0.lib",
        "api-ms-win-crt-time-l1-1-0.lib",
        "api-ms-win-crt-utility-l1-1-0.lib",
    ]
);
#[cfg(cato_macos_assets)]
define_target!(X86_64_MACOS, "x86_64-macos", ["runtime.o", "libSystem.tbd"]);
#[cfg(cato_macos_assets)]
define_target!(
    AARCH64_MACOS,
    "aarch64-macos",
    ["runtime.o", "libSystem.tbd"]
);

pub fn assets_for(target: &str) -> Result<&'static TargetAssets, String> {
    match target {
        "x86_64-linux" => Ok(&X86_64_LINUX),
        "aarch64-linux" => Ok(&AARCH64_LINUX),
        "x86_64-windows" => Ok(&X86_64_WINDOWS),
        #[cfg(cato_macos_assets)]
        "x86_64-macos" => Ok(&X86_64_MACOS),
        #[cfg(cato_macos_assets)]
        "aarch64-macos" => Ok(&AARCH64_MACOS),
        #[cfg(not(cato_macos_assets))]
        "x86_64-macos" | "aarch64-macos" => Err(format!(
            "cato: no embedded assets for target '{target}' (this cato build does not embed {target} — run tools/gen_assets.sh on macOS to generate them)"
        )),
        other => Err(format!(
            "cato: no embedded assets for target '{other}' (this cato build does not embed {other})"
        )),
    }
}

pub fn host_target_name() -> Option<&'static str> {
    if cfg!(all(target_os = "linux", target_arch = "x86_64")) {
        Some("x86_64-linux")
    } else if cfg!(all(target_os = "linux", target_arch = "aarch64")) {
        Some("aarch64-linux")
    } else if cfg!(all(target_os = "macos", target_arch = "x86_64")) {
        Some("x86_64-macos")
    } else if cfg!(all(target_os = "macos", target_arch = "aarch64")) {
        Some("aarch64-macos")
    } else if cfg!(all(target_os = "windows", target_arch = "x86_64")) {
        Some("x86_64-windows")
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn linux_targets_embed_runtime_and_libc() {
        for t in ["x86_64-linux", "aarch64-linux"] {
            let a = assets_for(t).expect(t);
            let names: Vec<&str> = a.files.iter().map(|(n, _)| *n).collect();
            for req in [
                "runtime.o",
                "crt1.o",
                "crti.o",
                "crtn.o",
                "libc.a",
                "libzigc.a",
                "libcompiler_rt.a",
            ] {
                assert!(names.contains(&req), "{t} missing {req}: {names:?}");
            }
            assert!(!a
                .files
                .iter()
                .find(|(n, _)| *n == "runtime.o")
                .unwrap()
                .1
                .is_empty());
        }
    }

    #[test]
    fn windows_target_embeds_mingw_crt() {
        let a = assets_for("x86_64-windows").expect("windows");
        let names: Vec<&str> = a.files.iter().map(|(n, _)| *n).collect();
        for req in [
            "runtime.o",
            "crt2.o",
            "libmingw32.a",
            "libzigc.a",
            "libcompiler_rt.a",
            "advapi32.lib",
            "kernel32.lib",
            "ntdll.lib",
            "shell32.lib",
            "user32.lib",
            "api-ms-win-crt-conio-l1-1-0.lib",
            "api-ms-win-crt-convert-l1-1-0.lib",
            "api-ms-win-crt-environment-l1-1-0.lib",
            "api-ms-win-crt-filesystem-l1-1-0.lib",
            "api-ms-win-crt-heap-l1-1-0.lib",
            "api-ms-win-crt-locale-l1-1-0.lib",
            "api-ms-win-crt-math-l1-1-0.lib",
            "api-ms-win-crt-multibyte-l1-1-0.lib",
            "api-ms-win-crt-private-l1-1-0.lib",
            "api-ms-win-crt-process-l1-1-0.lib",
            "api-ms-win-crt-runtime-l1-1-0.lib",
            "api-ms-win-crt-stdio-l1-1-0.lib",
            "api-ms-win-crt-string-l1-1-0.lib",
            "api-ms-win-crt-time-l1-1-0.lib",
            "api-ms-win-crt-utility-l1-1-0.lib",
        ] {
            assert!(names.contains(&req), "missing {req}: {names:?}");
        }
    }

    #[test]
    fn unknown_target_errors_with_pinned_message() {
        let e = assets_for("wasm32").expect_err("wasm has no native assets");
        assert_eq!(
            e,
            "cato: no embedded assets for target 'wasm32' (this cato build does not embed wasm32)"
        );
    }

    #[test]
    fn host_target_name_is_known_or_none() {
        let h = host_target_name();
        if let Some(h) = h {
            assert!(assets_for(h).is_ok() || h.ends_with("macos"));
        }
    }
}
